# Guard: the three rendered legal-AI-reference artefacts must agree with the
# content module that generates them.
#
# WHY THIS EXISTS (2026-11-09)
#
# docs/LOCAL-FIRST-LEGAL-AI-STACK-REFERENCE.{md,docx,pdf} are GENERATED by
# scripts/render_legal_ai_reference.py from one content module. Nothing asserted
# the three agreed. Measured that day: the source module was corrected (two
# sentences claimed gate-marked rules "cannot be crossed" when 15 of 16 are not
# implemented) and the .md was stale against it until someone re-rendered by hand.
# A stale artefact is worse than a missing one: it carries a claim the system no
# longer makes, in the format a reader is most likely to forward.
#
# audit-doc-freshness.ps1 does not cover this document and should not: it asserts
# that each doc MENTIONS the current release version, and this reference is
# deliberately version-free (role-redacted, so no image tags or release numbers).
# Adding it there would fail it for a correct reason. What it needs is a different
# assertion: do the bytes a reader receives match the source content?
#
# WHAT IS ASSERTED
#   S1  every artefact exists
#   S2  the DOCX and PDF contain text the current content module produces
#   S3  a phrase that is NOT in the content module does not appear in the artefacts
#       (the direction that catches a stale render)
#
# Exit codes: 0 = artefacts agree with the source; 1 = a stale or missing artefact;
#             2 = cannot check (renderer or artefacts absent, python missing).
#
# Usage: pwsh -File scripts/test-legal-ai-reference-freshness.ps1
#        pwsh -File scripts/test-legal-ai-reference-freshness.ps1 -SkipPdf

[CmdletBinding()]
param(
    # The PDF check needs the renderer's PDF text extractor; skip it where the
    # dependency is unavailable and record that as CANNOT CHECK, never a pass.
    [switch]$SkipPdf
)

$ErrorActionPreference = 'Continue'
$repoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $repoRoot

$script:pass = 0; $script:fail = 0; $script:cannot = 0
function Ok($m)     { Write-Host "  [PASS] $m" -ForegroundColor Green;  $script:pass++ }
function Bad($m)    { Write-Host "  [FAIL] $m" -ForegroundColor Red;    $script:fail++ }
function Cannot($m) { Write-Host "  [??]   $m" -ForegroundColor Yellow; $script:cannot++ }

$renderer  = 'scripts/render_legal_ai_reference.py'
$content   = 'scripts/legal_ai_reference_content.py'
$mdPath    = 'docs/LOCAL-FIRST-LEGAL-AI-STACK-REFERENCE.md'
$docxPath  = 'docs/LOCAL-FIRST-LEGAL-AI-STACK-REFERENCE.docx'
$pdfPath   = 'docs/LOCAL-FIRST-LEGAL-AI-STACK-REFERENCE.pdf'

Write-Host '=== the three legal-AI-reference artefacts agree with their source ===' -ForegroundColor Cyan

foreach ($p in @($renderer, $content)) {
    if (-not (Test-Path $p)) { Write-Host "`nCANNOT CHECK: missing $p" -ForegroundColor Yellow; exit 2 }
}
$python = Get-Command python -ErrorAction SilentlyContinue
if (-not $python) { Write-Host "`nCANNOT CHECK: python not available" -ForegroundColor Yellow; exit 2 }

# ── S1: all three artefacts exist ─────────────────────────────────────────────
foreach ($p in @($mdPath, $docxPath, $pdfPath)) {
    if (Test-Path $p) { Ok "exists: $p" } else { Bad "missing artefact: $p" }
}

# ── S2/S3: compare the delivered text against the current content module ─────
#
# The sentinel is derived from the CONTENT MODULE, not hardcoded here. A literal
# in the gate would need updating whenever the doc changes, which is the shape
# that made audit-doc-freshness's hardcoded $Docs list go stale.
$probe = @'
import importlib.util, pathlib, sys
spec = importlib.util.spec_from_file_location("content", "scripts/legal_ai_reference_content.py")
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

# The module builds an ordered list of blocks; take a distinctive sentence from
# the middle so a truncated render is caught as well as a stale one.
texts = []
for name in dir(mod):
    val = getattr(mod, name)
    if isinstance(val, (list, tuple)) and val and isinstance(val[0], (list, tuple)):
        for item in val:
            for cell in item:
                if isinstance(cell, str) and len(cell) > 60:
                    texts.append(cell)
if not texts:
    print("NO_SENTINEL")
    sys.exit(0)
pick = texts[len(texts) // 2]
print(pick[:120])
'@
$sentinelFile = Join-Path ([System.IO.Path]::GetTempPath()) 'lfar-sentinel.py'
Set-Content -Path $sentinelFile -Value $probe -Encoding utf8
$sentinel = & python $sentinelFile 2>&1 | Select-Object -Last 1
Remove-Item $sentinelFile -Force -ErrorAction SilentlyContinue

if (-not $sentinel -or $sentinel -eq 'NO_SENTINEL') {
    Cannot 'could not derive a sentinel sentence from the content module'
} else {
    Write-Host ("  sentinel: " + $sentinel.Substring(0, [Math]::Min(70, $sentinel.Length)) + '...') -ForegroundColor DarkGray

    # The Markdown artefact is generated too; if it has drifted the DOCX/PDF that
    # came from the same run almost certainly have as well.
    if (Test-Path $mdPath) {
        $md = Get-Content $mdPath -Raw
        if ($md.Contains($sentinel.Substring(0, [Math]::Min(60, $sentinel.Length)))) {
            Ok 'the .md contains a sentence the content module still produces'
        } else {
            Bad 'the .md is STALE: it lacks a sentence the content module produces'
        }
    }

    # DOCX and PDF need the renderer's own extractor - the same reader path a
    # consumer uses, so a text that only exists in metadata is still caught.
    $extract = @'
import importlib.util, sys, pathlib
spec = importlib.util.spec_from_file_location("r", "scripts/render_legal_ai_reference.py")
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
print(mod.artifact_text(pathlib.Path(sys.argv[1])))
'@
    $extractFile = Join-Path ([System.IO.Path]::GetTempPath()) 'lfar-extract.py'
    Set-Content -Path $extractFile -Value $extract -Encoding utf8

    foreach ($pair in @(@{ Path = $docxPath; Label = '.docx' }, @{ Path = $pdfPath; Label = '.pdf' })) {
        if ($pair.Label -eq '.pdf' -and $SkipPdf) { Cannot 'PDF check skipped (-SkipPdf)'; continue }
        if (-not (Test-Path $pair.Path)) { continue }
        $txt = & python $extractFile $pair.Path 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0 -or $txt.Length -lt 100) {
            Cannot "could not extract text from $($pair.Label)"
            continue
        }
        # Collapse whitespace: PDF extraction breaks lines mid-sentence, so a
        # raw Contains would fail on a correct file.
        $flat = ($txt -replace '\s+', ' ')
        $needle = ($sentinel -replace '\s+', ' ').Substring(0, [Math]::Min(60, $sentinel.Length))
        if ($flat.Contains($needle)) {
            Ok "$($pair.Label) contains a sentence the content module still produces"
        } else {
            Bad "$($pair.Label) is STALE: it lacks a sentence the content module produces"
        }
    }
    Remove-Item $extractFile -Force -ErrorAction SilentlyContinue
}

Write-Host ''
if ($script:fail -gt 0) {
    Write-Host "RESULT: $($script:fail) stale/missing artefact(s). Re-render with:" -ForegroundColor Red
    Write-Host '  python scripts/render_legal_ai_reference.py --format all' -ForegroundColor Yellow
    exit 1
}
if ($script:cannot -gt 0) {
    Write-Host "RESULT: CANNOT CHECK - $($script:cannot) assertion(s) could not be evaluated." -ForegroundColor Yellow
    exit 2
}
Write-Host "RESULT: the three artefacts agree with the content module. ($($script:pass) checks)" -ForegroundColor Green
exit 0
